rows = []
def add(base, lens, content, characteristic, strength, isolated="Yes", embedded="No"):
    r = list(core[base]); r[17:21] = [lens, content, characteristic, strength]; r[21]=isolated; r[22]=embedded; rows.append(r)

for content, char in [("Affect","positive affect/emotional wellbeing"),("Meaning-making and Self-concept","psychological wellbeing composite"),("Community and Interpersonal relationships","social wellbeing composite")]:
    add("lamers2012", "Subjective wellbeing" if content=="Affect" else ("Psychological wellbeing" if content.startswith("Meaning") else "Social wellbeing"), content, char, "PARTIAL", "No", "Yes")
add("hounkpatin2018", "Subjective wellbeing", "Appraisal", "life satisfaction", "DIRECT")
for lens,content,char in [("Subjective wellbeing","Affect","positive affect"),("Subjective wellbeing","Affect","infrequent negative affect"),("Subjective wellbeing","Appraisal","life satisfaction"),("Psychological wellbeing","Self-concept","self-esteem")]: add("fetvadjiev2019",lens,content,char,"DIRECT")
rows += [core["lamers2011"], core["joshanloo2016"]]
for lens,content,char,strength in [("Subjective wellbeing","Appraisal","life satisfaction","DIRECT"),("Social wellbeing","Interpersonal relationships","satisfaction with social contacts","DIRECT"),("Outside core HiFWB","NON_CORE_EXCLUDED","work satisfaction","NON_CORE_EXCLUDED")]: add("olaru2023",lens,content,char,strength)
for lens,content,char in [("Psychological wellbeing","Self-concept","self-esteem"),("Subjective wellbeing","Appraisal","life satisfaction")]: add("joshanloo2025",lens,content,char,"DIRECT")
rows.append(core["schellenberg2026"])
